; ---------------------------------------------------------------
; void __near__ load_room (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_load_room: near

.segment	"CODE"

;
; ppu_off();
;
	jsr     _ppu_off
;
; vram_adr(NAMETABLE_A);
;
	ldx     #$20
	lda     #$00
	jsr     _vram_adr
;
; for (largeindex = 0; largeindex < 1024; ++largeindex)
;
	lda     #$00
	sta     _largeindex
	sta     _largeindex+1
L1924:	ldx     _largeindex+1
	cpx     #$04
	bcs     L1925
;
; if (game_mode == MODE_TITLE)
;
	lda     _game_mode
	bne     L2B5A
;
; vram_put(title[largeindex]);
;
	lda     #<(_title)
	sta     ptr1
	lda     #>(_title)
	clc
	adc     _largeindex+1
	sta     ptr1+1
	ldy     _largeindex
;
; else if (game_mode == MODE_OPTIONS)
;
	jmp     L2B5B
L2B5A:	lda     _game_mode
	cmp     #$01
	bne     L1933
;
; vram_put(settings[largeindex]);
;
	lda     #<(_settings)
	sta     ptr1
	lda     #>(_settings)
	clc
	adc     _largeindex+1
	sta     ptr1+1
	ldy     _largeindex
;
; else
;
	jmp     L2B5B
;
; vram_put(map_ptr[largeindex]);
;
L1933:	lda     _map_ptr
	clc
	adc     _largeindex
	sta     ptr1
	lda     _map_ptr+1
	adc     _largeindex+1
	sta     ptr1+1
	ldy     #$00
L2B5B:	lda     (ptr1),y
	jsr     _vram_put
;
; for (largeindex = 0; largeindex < 1024; ++largeindex)
;
	inc     _largeindex
	bne     L1924
	inc     _largeindex+1
	jmp     L1924
;
; ppu_on_all();
;
L1925:	jmp     _ppu_on_all

.endproc

