.segment	"CODE"

;
; oam_clear();
;
	jsr     _oam_clear
;
; if (powerup1 == 1)
;
	lda     _powerup1
	cmp     #$01
	bne     L2B64
;
; if (map == MAP_COMBS)
;
	lda     _map
	bne     L2B62
;
; oam_meta_spr(COMBS_FLOWER_X[0], COMBS_FLOWER_Y[0], gamesprites_powerup_data);
;
	jsr     decsp2
	lda     _COMBS_FLOWER_X
	ldy     #$01
	sta     (sp),y
	lda     _COMBS_FLOWER_Y
;
; else if (map == MAP_VINES)
;
	jmp     L2B80
L2B62:	lda     _map
	cmp     #$02
	bne     L2B63
;
; oam_meta_spr(VINES_FLOWER_X[0], VINES_FLOWER_Y[0], gamesprites_powerup_data);
;
	jsr     decsp2
	lda     _VINES_FLOWER_X
	ldy     #$01
	sta     (sp),y
	lda     _VINES_FLOWER_Y
;
; else if (map == MAP_OUTDOORS)
