; ---------------------------------------------------------------
; void __near__ clear_background (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_clear_background: near

.segment	"CODE"

;
; ppu_off(); // screen off
;
	jsr     _ppu_off
;
; vram_adr(NAMETABLE_A);
;
	ldx     #$20
	lda     #$00
	jsr     _vram_adr
;
; for (tempint = 0; tempint < 1024; ++tempint)
;
	lda     #$00
	sta     _tempint
	sta     _tempint+1
L2AF2:	ldx     _tempint+1
	cpx     #$04
	bcs     L2AF3
;
; vram_put(0x00);
;
	lda     #$00
	jsr     _vram_put
;
; for (tempint = 0; tempint < 1024; ++tempint)
;
	inc     _tempint
	bne     L2AF2
	inc     _tempint+1
	jmp     L2AF2
;
; ppu_on_all(); // turn on screen
;
L2AF3:	jmp     _ppu_on_all

.endproc

